/* @autogenerated */
import { Component, inject } from '@angular/core';
import { Tenant } from 'app/features/identity/tenant/model/tenant.model';
import { TenantRepository } from 'app/features/identity/tenant/repository/tenant-repository.service';
import { ConfirmAction } from 'app/shared/toolkit/action/confirm-action';

@Component({ selector: 'tenant-view-enable-action', standalone: false, template: '' })
export class TenantViewEnableActionComponent extends ConfirmAction<Tenant> {
  readonly name = 'enable';
  protected readonly scope = 'identity/tenant';
  protected readonly repository = inject(TenantRepository);

  protected override appliesTo(items: Tenant[]) {
    return items.every((item) => !item.enabled);
  }

  protected execute([item]: Tenant[]) {
    return this.repository.enable(item.uid);
  }
}
